import{_ as e,o as l,c as n,a2 as r}from"./chunks/framework.BBdhqAg0.js";const s="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",h=JSON.parse('{"title":"분양 조건 설정","description":"","frontmatter":{},"headers":[],"relativePath":"project/settings.md","filePath":"project/settings.md","lastUpdated":1793455234000}'),d={name:"project/settings.md"};function g(a,t,o,i,x,y){return l(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="분양-조건-설정" tabindex="-1">분양 조건 설정 <a class="header-anchor" href="#분양-조건-설정" aria-label="Permalink to &quot;분양 조건 설정&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+s+'" alt="분양 조건 및 납부 회차 설정 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/settings.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>분양 조건 설정</strong>은 프로젝트의 납부 회차별 납부 일정, 계약금 및 세부 공급 가격, 구비 서류, 유상 옵션 등 분양 계약 체결과 수납 관리에 직접적으로 적용되는 핵심 계약 조건을 총괄 설정하는 모듈입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [프로젝트 설정] → [분양 조건 설정]**을 선택하여 접속합니다.</li></ul><h2 id="_1-납부-회차-등록" tabindex="-1">1. 납부 회차 등록 <a class="header-anchor" href="#_1-납부-회차-등록" aria-label="Permalink to &quot;1. 납부 회차 등록&quot;">​</a></h2><p>계약금, 중도금, 잔금 등 분양 대금의 납부 회차를 정의하고, 각 회차별 납부 기한 및 선납할인/연체가산 기준을 설정합니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 분양 조건 설정 &gt; 납부 회차 등록</code></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>타입 종류</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">공동주택, 오피스텔 등 시설 용도별 회차 구분</td></tr><tr><td style="text-align:left;"><strong>회차 종류</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">계약금, 중도금, 잔금, 업무대행비 등 회차 성격 선택</td></tr><tr><td style="text-align:left;"><strong>계약금 산정방법</strong></td><td style="text-align:center;"></td><td style="text-align:left;">(계약금인 경우) 등록 계약 금액 우선 또는 분양가 대비 비율 중 선택</td></tr><tr><td style="text-align:left;"><strong>납입회차 코드</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;"><strong>납부 시점(타이밍)</strong> 그룹화 코드. 동일 기한 내 납부 항목은 같은 코드 부여</td></tr><tr><td style="text-align:left;"><strong>납부순서</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;"><strong>수납 정산 우선순위</strong>. 입금 발생 시 장부상 먼저 채워지는 절대적 순서</td></tr><tr><td style="text-align:left;"><strong>회차 명 / 별칭</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">납부 고지서 등에 공식 표출될 회차 명칭 (예: <code>1차 계약금</code>, <code>중도금 1회차</code>)</td></tr><tr><td style="text-align:left;"><strong>납부 약정금액</strong></td><td style="text-align:center;"></td><td style="text-align:left;">정액으로 정해진 경우 입력 (예: 업무대행비 1,000만 원)</td></tr><tr><td style="text-align:left;"><strong>납부비율(%)</strong></td><td style="text-align:center;"></td><td style="text-align:left;">분양가 대비 납부 비율 (잔금은 100%에서 자동 계산)</td></tr><tr><td style="text-align:left;"><strong>납부 약정일</strong></td><td style="text-align:center;"></td><td style="text-align:left;">확정된 고정 납부 기한이 있는 경우 날짜 지정</td></tr><tr><td style="text-align:left;"><strong>전회 기준 경과일수</strong></td><td style="text-align:center;"></td><td style="text-align:left;">전 회차(예: 계약일)로부터 일정 기간 후 납부 시 설정 (예: 30일 이내)</td></tr><tr><td style="text-align:left;"><strong>선납/연체 설정</strong></td><td style="text-align:center;"></td><td style="text-align:left;">선납할인율, 연체가산율 및 각각의 적용 기준일 설정</td></tr></tbody></table><h3 id="💡-납입회차-코드-vs-납부순서-쉽게-이해하기" tabindex="-1">💡 납입회차 코드 vs 납부순서, 쉽게 이해하기 <a class="header-anchor" href="#💡-납입회차-코드-vs-납부순서-쉽게-이해하기" aria-label="Permalink to &quot;💡 납입회차 코드 vs 납부순서, 쉽게 이해하기&quot;">​</a></h3><p>두 항목을 명확히 구분하는 이유는 **&quot;동시에 내는 돈이라도 장부상 정산 순서가 다르기 때문&quot;**입니다.</p><ul><li><strong>납입회차 코드 (시점 - When)</strong>: &quot;언제 내는가?&quot; 즉, 고지서에 한 묶음으로 청구되는 <strong>납부 시점 그룹</strong>입니다.</li><li><strong>납부순서 (우선순위 - Priority)</strong>: &quot;무엇을 먼저 채우는가?&quot; 즉, 대금이 일부만 입금되었을 때의 <strong>장부 정산 순위</strong>입니다.</li></ul><p><strong>[실무 사례: 2회차 납부 기한에 계약금과 업무대행비를 각각 1,000만 원씩 받는 경우]</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">항목 명칭</th><th style="text-align:center;"><strong>회차 코드 (시점)</strong></th><th style="text-align:center;"><strong>납부 순서 (우선순위)</strong></th><th style="text-align:left;">시스템 정산 로직</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>2차 계약금</strong></td><td style="text-align:center;"><strong>2</strong></td><td style="text-align:center;"><strong>2</strong></td><td style="text-align:left;">입금 발생 시 가장 먼저 채워짐</td></tr><tr><td style="text-align:left;"><strong>업무대행비</strong></td><td style="text-align:center;"><strong>2</strong></td><td style="text-align:center;"><strong>3</strong></td><td style="text-align:left;">계약금이 다 채워진 후 남은 금액이 채워짐</td></tr></tbody></table><ul><li><strong>실제 작동</strong>: 만약 계약자가 2,000만 원 중 <strong>1,500만 원만 입금</strong>했다면, 시스템은 <strong>납부순서</strong>에 따라 <code>[2차 계약금]</code> 1,000만 원을 완납 처리하고, 남은 500만 원을 <code>[업무대행비]</code>의 일부 납부로 자동 배정합니다.</li></ul><h2 id="_2-계약-금액-등록" tabindex="-1">2. 계약 금액 등록 <a class="header-anchor" href="#_2-계약-금액-등록" aria-label="Permalink to &quot;2. 계약 금액 등록&quot;">​</a></h2><p>차수 및 타입별로 고정된 계약 금액을 설정합니다.</p><ul><li><strong>등록 대상</strong>: 동호 미지정 계약이나 타입별(층별 구분 없이) 일괄 정액제 계약금을 운영할 때 등록합니다.</li><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 분양 조건 설정 &gt; 계약 금액 등록</code></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>차수</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">대상 계약 차수 그룹 선택</td></tr><tr><td style="text-align:left;"><strong>타입</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">대상 유닛 타입 선택</td></tr><tr><td style="text-align:left;"><strong>회차별 납부금액</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 차수/타입에 적용할 정액 계약금액</td></tr></tbody></table><h2 id="_3-공급-가격-등록" tabindex="-1">3. 공급 가격 등록 <a class="header-anchor" href="#_3-공급-가격-등록" aria-label="Permalink to &quot;3. 공급 가격 등록&quot;">​</a></h2><p>동/타입/층별 범위에 따른 실제 공급 가격을 등록합니다. 건물가, 대지가, 부가세를 구분하여 관리합니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 분양 조건 설정 &gt; 공급 가격 등록</code></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>구분 / 차수 / 타입</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">가격을 등록할 상세 범위 선택</td></tr><tr><td style="text-align:left;"><strong>층별 조건</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">등록된 층 범위(저층부, 기준층 등) 선택</td></tr><tr><td style="text-align:left;"><strong>건물가 / 대지가</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">각 항목별 금액 입력 (단위: 원)</td></tr><tr><td style="text-align:left;"><strong>부가세</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">건물분에 대한 부가세(10%) 입력</td></tr><tr><td style="text-align:left;"><strong>기준공급가</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">건물가 + 대지가 + 부가세 합계 (시스템 자동 계산)</td></tr><tr><td style="text-align:left;"><strong>특별약정 추가</strong></td><td style="text-align:center;"></td><td style="text-align:left;">특정 회차에 대해 비율이 아닌 확정 금액을 적용할 경우 설정</td></tr></tbody></table><h3 id="전체-계약건-공급가-재설정-관리자-전용-기능" tabindex="-1">전체 계약건 공급가 재설정 (관리자 전용 기능) <a class="header-anchor" href="#전체-계약건-공급가-재설정-관리자-전용-기능" aria-label="Permalink to &quot;전체 계약건 공급가 재설정 (관리자 전용 기능)&quot;">​</a></h3><p>공급 가격이나 계약 금액 정보를 사후 수정한 후, 이미 등록된 모든 계약 데이터에 변경된 내용을 일괄 반영할 때 사용합니다.</p><ul><li><strong>미리보기</strong>: 실제 반영 전 업데이트 대상 계약 건수와 샘플 데이터를 화면의 팝업창을 통해 사전 검토합니다.</li><li><strong>전체 공급가 재설정</strong>: 현재 등록된 최신 공급 가격 및 계약 금액 데이터를 기반으로 모든 계약 건의 가격 정보를 강제로 재설정합니다.</li><li><strong>⚠️ 주의사항</strong>: 이 작업은 복구가 불가능하며 등록된 모든 계약 데이터의 수납 약정 금액이 변경될 수 있으므로 사전에 전산 담당자와 상의 후 매우 신중하게 실행해야 합니다.</li></ul><h2 id="_4-구비-서류-등록" tabindex="-1">4. 구비 서류 등록 <a class="header-anchor" href="#_4-구비-서류-등록" aria-label="Permalink to &quot;4. 구비 서류 등록&quot;">​</a></h2><p>계약 체결 시 계약자가 제출해야 하는 필수 증빙 서류 및 동의서 목록을 관리합니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 분양 조건 설정 &gt; 구비 서류 등록</code></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>서류구분</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">증빙서류(인감증명 등) 또는 동의서류(약정서, 개인정보동의 등) 중 선택</td></tr><tr><td style="text-align:left;"><strong>서류 유형</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">주민등록등본, 인감증명서, 신분증 사본 등 세부 유형 선택</td></tr><tr><td style="text-align:left;"><strong>필요 수량</strong></td><td style="text-align:center;"></td><td style="text-align:left;">제출받아야 할 서류 부수</td></tr><tr><td style="text-align:left;"><strong>필수 여부</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;"><code>필수</code>, <code>선택</code>, <code>조건부 필수</code> 중 선택</td></tr><tr><td style="text-align:left;"><strong>설명 / 표시 순서</strong></td><td style="text-align:center;"></td><td style="text-align:left;">서류 지참 안내 시 참고사항 및 목록 노출 순서</td></tr></tbody></table><h2 id="_5-옵션-품목-등록" tabindex="-1">5. 옵션 품목 등록 <a class="header-anchor" href="#_5-옵션-품목-등록" aria-label="Permalink to &quot;5. 옵션 품목 등록&quot;">​</a></h2><p>발코니 확장, 시스템 에어컨, 빌트인 가전 등 수분양자가 선택할 수 있는 유상 옵션 품목을 관리합니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 분양 조건 설정 &gt; 옵션 품목 등록</code></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>타입구분</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 옵션을 선택할 수 있는 대상 타입 (다중 선택 가능)</td></tr><tr><td style="text-align:left;"><strong>품목 코드 / 이름</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">옵션 품목 식별 정보 (예: <code>발코니확장</code>, <code>시스템에어컨4대</code>)</td></tr><tr><td style="text-align:left;"><strong>세대 옵션</strong></td><td style="text-align:center;"></td><td style="text-align:left;">규격, 색상 등 세부 선택 사항</td></tr><tr><td style="text-align:left;"><strong>제조사</strong></td><td style="text-align:center;"></td><td style="text-align:left;">품목의 제조사 또는 브랜드</td></tr><tr><td style="text-align:left;"><strong>옵션 가격</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">총 판매 가격</td></tr><tr><td style="text-align:left;"><strong>계약금 / 잔금</strong></td><td style="text-align:center;"></td><td style="text-align:left;">옵션 대금 분납 시 각 금액 설정</td></tr></tbody></table><h2 id="_6-💡-분양가-및-납부-금액-산출-우선순위-요약" tabindex="-1">6. 💡 분양가 및 납부 금액 산출 우선순위 요약 <a class="header-anchor" href="#_6-💡-분양가-및-납부-금액-산출-우선순위-요약" aria-label="Permalink to &quot;6. 💡 분양가 및 납부 금액 산출 우선순위 요약&quot;">​</a></h2><p>IBS 시스템은 복잡한 분양 전략을 완벽히 소화하기 위해 다단계 우선순위 로직을 사용합니다.</p><h3 id="_1-공급-가격-산출-우선순위" tabindex="-1">1. 공급 가격 산출 우선순위 <a class="header-anchor" href="#_1-공급-가격-산출-우선순위" aria-label="Permalink to &quot;1. 공급 가격 산출 우선순위&quot;">​</a></h3><p>시스템은 계약서 생성 시 <strong>[개별 계약 가격 &gt; 기준 공급 가격 &gt; 예산 단가 &gt; 타입 단가]</strong> 순으로 유효한 값을 찾아 적용합니다. 따라서 상세한 공급 가격표를 등록하기 전이라도 예산이나 타입 정보만 있다면 대략적인 분양가 산출이 가능합니다.</p><h3 id="_2-회차별-납부-금액-산출-우선순위" tabindex="-1">2. 회차별 납부 금액 산출 우선순위 <a class="header-anchor" href="#_2-회차별-납부-금액-산출-우선순위" aria-label="Permalink to &quot;2. 회차별 납부 금액 산출 우선순위&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">순위</th><th style="text-align:left;">항목 명칭</th><th style="text-align:left;">설정 메뉴</th><th style="text-align:left;">적용 범위 (Scope)</th><th style="text-align:left;">실무 활용 예시</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1순위</strong></td><td style="text-align:left;"><strong>회차별 고정 금액</strong></td><td style="text-align:left;">[납부 회차 등록]</td><td style="text-align:left;"><strong>프로젝트 전체</strong></td><td style="text-align:left;">모든 세대의 업무대행비를 1,000만 원으로 고정할 때</td></tr><tr><td style="text-align:center;"><strong>2순위</strong></td><td style="text-align:left;"><strong>특별 약정 금액</strong></td><td style="text-align:left;">[공급 가격 등록]</td><td style="text-align:left;"><strong>특정 가격 조건</strong></td><td style="text-align:left;">펜트하우스만 계약금을 5,000만 원 정액으로 받을 때</td></tr><tr><td style="text-align:center;"><strong>3순위</strong></td><td style="text-align:left;"><strong>타입별 계약 금액</strong></td><td style="text-align:left;">[계약 금액 등록]</td><td style="text-align:left;"><strong>특정 타입별</strong></td><td style="text-align:left;">84타입 전체에 동일한 3,000만 원 정액 계약금을 걸 때</td></tr><tr><td style="text-align:center;"><strong>4순위</strong></td><td style="text-align:left;"><strong>납부 비율 계산</strong></td><td style="text-align:left;">[납부 회차 등록]</td><td style="text-align:left;"><strong>프로젝트 전체</strong></td><td style="text-align:left;">(기본값) 공급가에 비율(10%, 60% 등)을 곱해 산출</td></tr></tbody></table><ul><li><strong>잔금 자동 보정</strong>: 잔금은 <code>[총 공급가 - (계약금 + 중도금 + 기타 회차 합계)]</code>로 시스템이 자동 계산하여 단수 차액을 완벽하게 맞춥니다.</li></ul>',40)])])}const f=e(d,[["render",g]]);export{h as __pageData,f as default};
